import{_ as t,c as s,o as n,j as e,a as r}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"《溫公易說》簡介","description":"溫公易說 - 《溫公易說》簡介","frontmatter":{"title":"《溫公易說》簡介","description":"溫公易說 - 《溫公易說》簡介"},"headers":[],"relativePath":"classics/wengong/001.md","filePath":"classics/wengong/001.md"}'),l={name:"classics/wengong/001.md"};function o(c,a,i,d,p,m){return n(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"《溫公易說》簡介",tabindex:"-1"},[r("《溫公易說》簡介 "),e("a",{class:"header-anchor",href:"#《溫公易說》簡介","aria-label":"Permalink to “《溫公易說》簡介”"},"​")],-1),e("p",null,"《溫公易說》是北宋時期著名政治家、史學家司馬光的易學著作。司馬光，字君實，號迂叟，世稱涑水先生，封溫國公，故後世稱其為司馬溫公。他歷仕仁宗、英宗、神宗、哲宗四朝，官至尚書左僕射兼門下侍郎，反對王安石變法，為保守派領袖，以清廉和正直著稱。",-1),e("p",null,"《溫公易說》原書已亡佚，現存版本是清代在編纂《四庫全書》時從《永樂大典》中輯出的，根據《宋史·藝文志》的記載重新編排為六卷。該書的解說相對簡略，對諸卦的解釋有多有少，有的卦甚至沒有解釋，只有《繫辭傳》部分解說較為詳細，而《說卦傳》以下的內容僅有兩條。一些學者如陳振孫認為這本書並未完成。",-1),e("p",null,"司馬光在《溫公易說》中主要闡明人事，不雜佛老之說，其解釋多不襲先儒舊說，而是以儒家“中庸”思想立論，強調剛柔相濟、中正之道。例如，他解釋《同人》卦時提出“君子樂與人同，小人樂與人異”，以及《坎》卦的《大象》解釋水流和人學習的過程，都顯示了他將易學理論聯繫到日常生活中，使之更貼近實用。",-1),e("p",null,"此書在易學發展史上佔有一席之地，成為宋人解《易》中的一個獨特流派。通行的版本包括《叢書集成》初編本、《四庫全書》本、《經苑》本及《榕園叢書》甲集本。",-1)])])}const u=t(l,[["render",o]]);export{f as __pageData,u as default};
